mapper.select:
select T2.SEC_ACCT_ID secAcctId, T2.SEC_ACCT_NAME secAcctName, T2.SEC_ACCT_SOURCE secAcctSource, T2.REGIST_ORG registOrg, T2.TRD_ACCT_ID trdAcctId, T2.REC_ACCT_ID recAcctId, T2.REMARK remark, T2.CREATE_USER createUser, T2.CREATE_DEPT createDept,T2.CREATE_TIME createTime, T2.UPDATE_USER updateUser, T2.UPDATE_TIME updateTime from PTL_SEC_ACCT T1 ,STL_SEC_ACCT_INFO T2 where T1.ACCT_NO=T2.SEC_ACCT_ID AND ( T2.SEC_ACCT_ID in
null) OR T2.SEC_ACCT_ID in (
#{item.secAcctId,jdbcType=VARCHAR}
) AND IFNULL(T2.sec_acct_type, 'SEC') = 'SEC'

select t.ACCT_NO, R.ACCT_NAME, t.PORTFOLIO_ID as parentId, v.SEC_ACCT_ID, v.TRADE_PLACE, t.CCY from PTL_CAPACCT_INFO t left join STL_SEC_ACCT_INFO v on t.ACCT_NO = v.TRD_ACCT_ID LEFT JOIN STL_CAPACCT_INFO R ON T.ACCT_NO = R.ACCT_NO AND T.CCY = R.CCY LEFT JOIN PTL_SEC_ACCT PSA ON v.SEC_ACCT_ID = PSA.ACCT_NO
t.ACCT_TYPE = 'A07'
and t.PORTFOLIO_ID = #{portfolioId} AND PSA.PORTFOLIO_ID = #{portfolioId}
and v.TRADE_PLACE = #{tradeMarket}
and t.ACCT_NO = #{acctNo}
and t.ACCT_NO = #{initValue}
AND t.ACCT_NO like concat('%',concat(#{search},'%'))
order by t.ACCT_NO

select a.finprod_id as id,a.finprod_abbr as text from fin_product a

	AND (a.finprod_id like concat('%',concat(#{search},'%')) OR a.finprod_abbr like concat('%',concat(#{search},'%')))


	and a.finprod_id = #{initValue}

select SEC_ACCT_ID id, SEC_ACCT_NAME text FROM STL_SEC_ACCT_INFO WHERE IFNULL(STL_SEC_ACCT_INFO.sec_acct_type, 'SEC') = 'SEC'/*只查询证券账户*/
AND (SEC_ACCT_ID like concat('%',concat(#{search},'%')) OR SEC_ACCT_NAME like concat('%',concat(#{search},'%')))
and SEC_ACCT_ID = #{initValue}

select fp.finprod_id id,fp.finprod_market_id text from FIN_PRODUCT fp


		fp.finprod_market_id = #{secId}



			#{item}

SELECT IFNULL(100-sum(IFNULL(FCP.PRIN_AMT,0)),100) "faceValue" ,FP.FINPROD_MARKET_ID "finprodMarketId"
FROM FIN_CASH_PLAN FCP
INNER JOIN FIN_PRODUCT FP ON FCP.FINPROD_ID = FP.FINPROD_ID

	/*TO_DATE(#{tradeDate},'yyyy-MM-dd')*/ STR_TO_DATE(#{tradeDate},'%Y-%m-%d') >= FCP.MDATE


			#{item}



GROUP BY FP.FINPROD_MARKET_ID

with ZYSHG as (select '204001.SH' as item_code, 'GC001' as item_value from dual union select '204002.SH' as item_code, 'GC002' as item_value from dual union select '204003.SH' as item_code, 'GC003' as item_value from dual union select '204004.SH' as item_code, 'GC004' as item_value from dual union select '204007.SH' as item_code, 'GC007' as item_value from dual union select '204014.SH' as item_code, 'GC014' as item_value from dual union select '204028.SH' as item_code, 'GC028' as item_value from dual union select '204091.SH' as item_code, 'GC091' as item_value from dual union select '204182.SH' as item_code, 'GC182' as item_value from dual union select '131810.SZ' as item_code, 'R-001' as item_value from dual union select '131811.SZ' as item_code, 'R-002' as item_value from dual union select '131800.SZ' as item_code, 'R-003' as item_value from dual union select '131809.SZ' as item_code, 'R-004' as item_value from dual union select '131801.SZ' as item_code, 'R-007' as item_value from dual union select '131802.SZ' as item_code, 'R-014' as item_value from dual union select '131803.SZ' as item_code, 'R-028' as item_value from dual union select '131805.SZ' as item_code, 'R-091' as item_value from dual union select '131806.SZ' as item_code, 'R-182' as item_value from dual) select distinct t.finprod_market_id as id, t.finprod_name as text, '${acctTradeMarket}' as parentId, t.oth_code_type, t.finprod_type2, t.finprod_id, t.trade_market, t.MARKET_ID, t.BOARD, t.TYPE_6, t.TYPE_7, t.IS_NET_SETT, t.FACE_VALUE from (
select t.oth_code as finprod_market_id, /*t.oth_code || '|' || v.finprod_abbr ||*/ concat(concat(concat(t.oth_code,'|'),v.finprod_abbr), (case t.oth_type when #{FINPROD_OTH_CODE_TYPE_05} then '配债' when #{FINPROD_OTH_CODE_TYPE_06} then '配股' end)) as finprod_name, /*decode(t.oth_type,#{FINPROD_OTH_CODE_TYPE_05},'配债',#{FINPROD_OTH_CODE_TYPE_06},'配股') as finprod_name,*/ t.oth_type oth_code_type, v.finprod_type2 finprod_type2, v.finprod_id, v.trade_market, v.FINPROD_MARKET_ID AS MARKET_ID, null AS BOARD, null AS TYPE_6, null AS TYPE_7, null AS IS_NET_SETT, v.mdate, va.FACE_VALUE FACE_VALUE from fin_product_oth_code t left join fin_product v on t.finprod_id = v.finprod_id left join fin_product_add va on va.finprod_id = v.finprod_id and ((va.TRADE_PLAT like concat('%',concat(#{tradePlat},'%')) and v.finprod_type2 = 'F01') or v.finprod_type2 != 'F01') where t.branch = 0 and t.oth_type in (#{FINPROD_OTH_CODE_TYPE_05}, #{FINPROD_OTH_CODE_TYPE_06})
and t.oth_type in (#{FINPROD_OTH_CODE_TYPE_06})
union
select a.finprod_market_id, concat(concat(a.finprod_market_id,'|'),a.finprod_abbr) as finprod_name, null as oth_code_type, a.finprod_type2, a.finprod_id, a.trade_market, a.finprod_market_id AS MARKET_ID, b.BOARD, r.TYPE_6, r.TYPE_7, b.IS_NET_SETT, a.mdate, b.FACE_VALUE FACE_VALUE from fin_product a left join fin_product_add b on b.FINPROD_ID = a.FINPROD_ID left join fin_product_type r on a.FINPROD_ID = r.FINPROD_ID where a.trade_market in (#{TRADE_PLACE_03}, #{TRADE_PLACE_04})
and a.trade_market = #{acctTradeMarket}
and (((b.TRADE_PLAT like concat('%',concat(#{tradePlat},'%')) or b.TRADE_PLAT is null) and a.finprod_type2 = 'F01') or a.finprod_type2 != 'F01')
and(((b.TRADE_PLAT like concat('%',concat(#{tradePlat},'%')) or b.TRADE_PLAT like concat('%', concat('05', '%')) or b.TRADE_PLAT is null) and a.finprod_type2 = 'F01') or a.finprod_type2 != 'F01')
and a.finprod_type2 in (#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10})
and a.finprod_type2 in (#{FINPROD_TYPE_TG_F01}, #{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10})
and a.finprod_type2 in (#{FINPROD_TYPE_TG_F01})
union select distinct a.item_code as finprod_market_id, concat(concat(a.item_code,'|'),a.item_value) as finprod_name, null as oth_code_type, #{FINPROD_TYPE_TG_ZYSHG} as finprod_type2, a.item_value as finprod_id, case when a.item_value in ('GC001', 'GC002', 'GC003', 'GC004', 'GC007', 'GC014', 'GC028', 'GC091', 'GC182') then #{TRADE_PLACE_03} when a.item_value IN ('R-001', 'R-002', 'R-003', 'R-004', 'R-007', 'R-014', 'R-028', 'R-091', 'R-182', 'RC001', 'RC003', 'RC007') then #{TRADE_PLACE_04} else null end as trade_market, a.item_code AS MARKET_ID, null AS BOARD, null AS TYPE_6, null AS TYPE_7, null AS IS_NET_SETT, null AS mdate, null AS FACE_VALUE from ZYSHG a
) t
and t.FINPROD_TYPE2 = #{finprodType2}
and t.TRADE_MARKET = #{acctTradeMarket}
and t.TRADE_MARKET = #{TRADE_PLACE_03}
and t.FINPROD_MARKET_ID = #{secId}
and (t.mdate > STR_TO_DATE(#{expireSettleDate},'%Y-%m-%d') or t.mdate is null)
and t.oth_code_type = #{othCodeType}
and t.FINPROD_MARKET_ID = #{initValue}
AND (t.finprod_market_id like concat('%',concat(#{search},'%')) OR t.finprod_name like concat('%',concat(#{search},'%')))

with ZYSHG as (select '204001.SH' as item_code, 'GC001' as item_value from dual union select '204002.SH' as item_code, 'GC002' as item_value from dual union select '204003.SH' as item_code, 'GC003' as item_value from dual union select '204004.SH' as item_code, 'GC004' as item_value from dual union select '204007.SH' as item_code, 'GC007' as item_value from dual union select '204014.SH' as item_code, 'GC014' as item_value from dual union select '204028.SH' as item_code, 'GC028' as item_value from dual union select '204091.SH' as item_code, 'GC091' as item_value from dual union select '204182.SH' as item_code, 'GC182' as item_value from dual union select '131810.SZ' as item_code, 'R-001' as item_value from dual union select '131811.SZ' as item_code, 'R-002' as item_value from dual union select '131800.SZ' as item_code, 'R-003' as item_value from dual union select '131809.SZ' as item_code, 'R-004' as item_value from dual union select '131801.SZ' as item_code, 'R-007' as item_value from dual union select '131802.SZ' as item_code, 'R-014' as item_value from dual union select '131803.SZ' as item_code, 'R-028' as item_value from dual union select '131805.SZ' as item_code, 'R-091' as item_value from dual union select '131806.SZ' as item_code, 'R-182' as item_value from dual) select distinct t.finprod_market_id as id, t.finprod_name as text, '${acctTradeMarket}' as parentId, t.oth_code_type, t.finprod_type2, t.finprod_id, t.trade_market, t.MARKET_ID, t.BOARD, t.TYPE_6, t.TYPE_7, t.IS_NET_SETT, t.FACE_VALUE, t.IS_NETPRICE from ( select a.finprod_market_id, concat(concat(a.finprod_market_id,'|'),a.finprod_abbr) as finprod_name, null as oth_code_type, a.finprod_type2, a.finprod_id, a.trade_market, a.finprod_market_id AS MARKET_ID, b.BOARD, r.TYPE_6, r.TYPE_7, b.IS_NET_SETT, a.mdate, b.FACE_VALUE FACE_VALUE, b.IS_NETPRICE IS_NETPRICE from fin_product a left join fin_product_add b on b.FINPROD_ID = a.FINPROD_ID left join fin_product_type r on a.FINPROD_ID = r.FINPROD_ID where a.trade_market in (#{TRADE_PLACE_03}, #{TRADE_PLACE_04})
and a.trade_market = #{acctTradeMarket}
and a.finprod_type2 in (#{FINPROD_TYPE_TG_F01}) union select distinct a.item_code as finprod_market_id, concat(concat(a.item_code,'|'),a.item_value) as finprod_name, null as oth_code_type, #{FINPROD_TYPE_TG_ZYSHG} as finprod_type2, a.item_value as finprod_id, case when a.item_value in ('GC001', 'GC002', 'GC003', 'GC004', 'GC007', 'GC014', 'GC028', 'GC091', 'GC182') then #{TRADE_PLACE_03} when a.item_value IN ('R-001', 'R-002', 'R-003', 'R-004', 'R-007', 'R-014', 'R-028', 'R-091', 'R-182', 'RC001', 'RC003', 'RC007') then #{TRADE_PLACE_04} else null end as trade_market, a.item_code AS MARKET_ID, null AS BOARD, null AS TYPE_6, null AS TYPE_7, null AS IS_NET_SETT, null AS mdate, null AS FACE_VALUE, null AS IS_NETPRICE from ZYSHG a ) t
and t.FINPROD_TYPE2 = #{finprodType2}
and t.TRADE_MARKET = #{acctTradeMarket}
and t.FINPROD_MARKET_ID = #{secId}
and (t.mdate > STR_TO_DATE(#{expireSettleDate},'%Y-%m-%d') or t.mdate is null)
and t.FINPROD_MARKET_ID = #{initValue}
AND (t.finprod_market_id like concat('%',concat(#{search},'%')) OR t.finprod_name like concat('%',concat(#{search},'%')))
